use opensip_platform::admit_harness_descriptor;
use std::fs::OpenOptions;
use std::io::Write;
use std::os::fd::AsRawFd;

fn main() {
    let mut args = std::env::args_os().skip(1);
    let channel_path = args.next().unwrap();
    let unrelated_path = args.next().unwrap();
    let mut original = OpenOptions::new().write(true).create_new(true).open(channel_path).unwrap();
    assert_eq!(original.as_raw_fd(), 3);
    let mut first = admit_harness_descriptor().unwrap();
    let mut second = admit_harness_descriptor().unwrap();
    let freed = first.as_raw_fd();
    assert_ne!(freed, 3);
    assert_ne!(second.as_raw_fd(), 3);
    assert_ne!(freed, second.as_raw_fd());
    println!("original={} first={} second={}", original.as_raw_fd(), freed, second.as_raw_fd());
    first.write_all(b"FIRST;").unwrap();
    drop(first);
    let unrelated = OpenOptions::new().write(true).create_new(true).open(unrelated_path).unwrap();
    assert_eq!(unrelated.as_raw_fd(), freed);
    println!("reused_descriptor={}", unrelated.as_raw_fd());
    second.write_all(b"SECOND;").unwrap();
    drop(second);
    original.write_all(b"ORIGINAL-STILL-OPEN").unwrap();
    drop(original);
    drop(unrelated);
    println!("independent_owners_and_reuse_ok=true");
}
